/*
 * The browser Supabase client.
 *
 * This carried the header "This file is automatically generated. Do not edit
 * it directly." Nothing generates it — no script in this repository writes it,
 * and everything below the imports is hand-written: the API-key fetch shim, the
 * configuration resolver, the lazy proxy. The header was inherited from the
 * scaffold and, left in place, tells the next person their fix here will be
 * overwritten. It will not.
 */
import { createClient } from "@supabase/supabase-js";
import type { Database } from "./types";
import { missingSupabaseConfigurationMessage } from "./configuration-message";
import {
  getSupabaseBrowserConfiguration,
  resolveSupabaseBrowserConfiguration,
  type SupabaseBrowserConfiguration,
} from "./configuration";

/*
 * RE-EXPORTED, SO NO CALL SITE HAD TO LEARN A SECOND NAME.
 *
 * The definitions moved to `configuration.ts` because reading them used to
 * require constructing a client — see that file. Anything importing them from
 * here still gets them; anything that ONLY wants them should import
 * `./configuration` directly and stay off the auth stack's import graph.
 */
export {
  getSupabaseBrowserConfiguration,
  resolveSupabaseBrowserConfiguration,
  type SupabaseBrowserConfiguration,
};

function isNewSupabaseApiKey(value: string): boolean {
  return value.startsWith("sb_publishable_") || value.startsWith("sb_secret_");
}

function createSupabaseFetch(supabaseKey: string): typeof fetch {
  return (input, init) => {
    const headers = new Headers(
      typeof Request !== "undefined" && input instanceof Request ? input.headers : undefined,
    );

    if (init?.headers) {
      new Headers(init.headers).forEach((value, key) => headers.set(key, value));
    }

    // New Supabase API keys are opaque strings, not bearer JWTs.
    if (
      isNewSupabaseApiKey(supabaseKey) &&
      headers.get("Authorization") === `Bearer ${supabaseKey}`
    ) {
      headers.delete("Authorization");
    }

    headers.set("apikey", supabaseKey);
    return fetch(input, { ...init, headers });
  };
}

function createSupabaseClient() {
  const config = getSupabaseBrowserConfiguration();
  const SUPABASE_URL = config.url;
  const SUPABASE_PUBLISHABLE_KEY = config.publishableKey;

  if (!SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) {
    const message = missingSupabaseConfigurationMessage(config.missing);
    console.error(`[Supabase] ${message}`);
    throw new Error(message);
  }

  return createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
    global: {
      fetch: createSupabaseFetch(SUPABASE_PUBLISHABLE_KEY),
    },
    auth: {
      /*
       * Ordinary browser storage, and the library's own default key: the one
       * auth storage authority. Never broker the session to a parent frame.
       */
      persistSession: true,
      autoRefreshToken: true,
      /*
       * A SESSION ARRIVES ONLY BY A FLOW THIS BROWSER STARTED. The default
       * (implicit) flow accepted tokens from any address's fragment, so a link
       * like ocade.in/#access_token=… signed the visitor into whatever account
       * the link's author chose, and their next chats went there. With PKCE,
       * Google's answer is a one-time code that only the browser holding the
       * matching secret can exchange (auth.callback.tsx), and tokens in an
       * address are refused.
       */
      flowType: "pkce",
    },
  });
}

let _supabase: ReturnType<typeof createSupabaseClient> | undefined;

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";
export const supabase = new Proxy({} as ReturnType<typeof createSupabaseClient>, {
  get(_, prop, receiver) {
    if (!_supabase) _supabase = createSupabaseClient();
    return Reflect.get(_supabase, prop, receiver);
  },
});
